import{_ as s,o as t,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Versions et compatibilité","description":"Numérotation, migrations de données et mises à jour sûres pour ATLAS et ses plugins.","frontmatter":{"title":"Versions et compatibilité","description":"Numérotation, migrations de données et mises à jour sûres pour ATLAS et ses plugins."},"headers":[],"relativePath":"fr/projects/atlas-plugins/developers/compatibility.md","filePath":"fr/projects/atlas-plugins/developers/compatibility.md","lastUpdated":1793126673000}'),r={name:"fr/projects/atlas-plugins/developers/compatibility.md"};function a(o,e,u,l,c,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="versions-et-compatibilite" tabindex="-1">Versions et compatibilité <a class="header-anchor" href="#versions-et-compatibilite" aria-label="Permalink to &quot;Versions et compatibilité&quot;">​</a></h1><p>Ces règles de publication s&#39;appliquent à partir du 15 octobre 2026. L&#39;App 0.1.302 ajoute un contrôle automatique avant installation et mise à jour des plugins ; 0.1.303 détecte aussi la version HA connectée. Les installations et formats existants ne sont pas migrés.</p><h2 id="quelle-version-utiliser" tabindex="-1">Quelle version utiliser ? <a class="header-anchor" href="#quelle-version-utiliser" aria-label="Permalink to &quot;Quelle version utiliser ?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Signification</th></tr></thead><tbody><tr><td>App/runtime ATLAS</td><td>Version du paquet Docker, App/Add-on ou Linux distribué.</td></tr><tr><td>Intégration HA</td><td>Version de <code>atlas_frontend</code> ; noter séparément le commit HACS.</td></tr><tr><td>Framework</td><td>Version indépendante pour chaque paquet <code>@atlas/*</code>, distincte de celle de l&#39;App.</td></tr><tr><td>Plugin</td><td>Version indépendante et identifiant stable ; manifeste, catalogue et paquet doivent correspondre.</td></tr><tr><td>Format des données</td><td>Type et version du format enregistré ; une révision compte les changements pour détecter les conflits.</td></tr></tbody></table><p>Le Card Editor est livré avec ATLAS. Les plugins externes sont mis à jour indépendamment. Des numéros identiques entre composants ne prouvent pas leur compatibilité.</p><h2 id="regles-de-publication" tabindex="-1">Règles de publication <a class="header-anchor" href="#regles-de-publication" aria-label="Permalink to &quot;Règles de publication&quot;">​</a></h2><p>Utiliser <code>MAJOR.MINOR.PATCH</code> : PATCH pour les corrections compatibles, MINOR pour les fonctions compatibles et MAJOR pour les ruptures après stabilisation d&#39;une interface 1.x. Avant 1.0, une rupture exige une nouvelle version MINOR et des instructions de migration. Une future rupture ne doit donc pas être publiée comme un autre correctif 0.1.x. Les anciennes versions ne sont pas renommées.</p><p>Les versions alpha désignent explicitement des versions de test. Un paquet publié dont le contenu change doit recevoir une nouvelle version ; une modification documentaire seule n&#39;exige pas de nouvelle version du runtime. Indiquer le commit source et les combinaisons testées dans les notes de publication.</p><h2 id="que-verifie-atlas-aujourd-hui" tabindex="-1">Que vérifie ATLAS aujourd&#39;hui ? <a class="header-anchor" href="#que-verifie-atlas-aujourd-hui" aria-label="Permalink to &quot;Que vérifie ATLAS aujourd&#39;hui ?&quot;">​</a></h2><p>Les champs de dépôt <code>compatibility.atlas</code>, <code>host</code> et <code>homeAssistant</code> décrivent la compatibilité annoncée. <code>atlas</code> désigne l&#39;App/runtime. Depuis 0.1.302, le serveur contrôle ensemble les déclarations du catalogue, du paquet et du manifeste inclus avant remplacement. Les plages SemVer comme <code>&gt;=0.1.302 &lt;0.2.0</code> sont évaluées. Une incompatibilité connue ou une condition invalide bloque le paquet et conserve la version installée. Une information absente signifie <strong>non vérifié</strong> et exige une confirmation explicite. Les plugins installés ne sont pas désactivés.</p><p><code>host</code> accepte un nom ou une liste d&#39;alternatives. <code>administration-local</code> conserve son sens historique d&#39;installateur Node commun ; <code>docker</code>, <code>linux</code> et <code>homeassistant</code> correspondent à la cible configurée. La confirmation ne contourne pas une incompatibilité connue. L&#39;aperçu n&#39;écrit aucun fichier ; le serveur vérifie à nouveau lors de l&#39;installation. Les imports locaux sont aussi contrôlés.</p><p>Depuis 0.1.303, l&#39;Administration détecte la version HA via la réponse authentifiée <code>/api/config</code> de la connexion configurée. Les jetons et toute autre configuration HA restent sur le serveur. Une condition HA déclenche une nouvelle requête avant l&#39;aperçu et l&#39;installation ; les versions fournies par le navigateur sont ignorées. Des identifiants absents, délais dépassés, redirections, accès refusés ou réponses invalides restent <strong>inconnus</strong> et exigent une vérification explicite. Une ancienne valeur valide n&#39;est jamais réutilisée. Les versions bêta, RC et de développement restent des préversions. Les champs inconnus exigent toujours une vérification. L&#39;endpoint en lecture seule <code>/api/homeassistant/version</code> retourne uniquement les métadonnées de version filtrées ou une raison fixe d&#39;échec ; il ne modifie ni paramètres ni projets.</p><p>La recherche de mises à jour compare numériquement les textes des versions ; ce n&#39;est pas un résolveur SemVer complet. Séparément, les dépendances des modules du noyau acceptent les triplets numériques exacts, <code>^</code> et <code>*</code>, mais pas les plages générales ni les préversions. Pour une version majeure zéro, le contrôle caret actuel conserve la même version MINOR ; <code>^0.0.3</code> accepte aussi <code>0.0.4</code>. Préférer des versions exactes pour ces modules.</p><p>L&#39;identifiant et la version du paquet sont comparés au manifeste avant remplacement ; les mises à jour par dépôt doivent aussi correspondre à la version du catalogue. Les capacités déclarées ne sont ni des autorisations automatiques ni un bac à sable. Des versions compatibles ne remplacent ni les tests fonctionnels ni l&#39;évaluation de confiance d&#39;un plugin.</p><h2 id="preserver-et-restaurer-les-donnees" tabindex="-1">Préserver et restaurer les données <a class="header-anchor" href="#preserver-et-restaurer-les-donnees" aria-label="Permalink to &quot;Préserver et restaurer les données&quot;">​</a></h2><ol><li>Avant une mise à jour, sauvegarder HA et les données ATLAS, ou l&#39;installation autonome avec ses données et son identité. Exporter aussi les paramètres Admin locaux, projets et métadonnées partagées des plugins. Les données propres aux plugins et collections du navigateur demandent des sauvegardes distinctes.</li><li>Conserver l&#39;adresse du runtime, les chemins persistants et l&#39;identité. Les paramètres chiffrés ne deviennent pas automatiquement transférables vers une autre installation. Une sauvegarde du code ne remplace pas celle des données.</li><li>Mettre à jour un composant à la fois ; redémarrer HA après les mises à jour de l&#39;intégration comme indiqué. Vérifier ensuite paramètres, projets et plugins actifs.</li><li>Restaurer ensemble le code <strong>et</strong> les données correspondantes. Un ancien programme ne doit pas écraser un format plus récent inconnu.</li></ol><p>Les futures migrations exigent un aperçu sans écriture, la sauvegarde de l&#39;original, la transformation et validation d&#39;une copie, une application explicite, le contrôle des conflits et un remplacement atomique. Ne jamais remplacer un format inconnu ou corrompu par des données vides. Répétitions et échecs doivent préserver les données. Ce sont des exigences, pas une migration universelle déjà disponible.</p><p>Depuis ATLAS 0.1.304, chaque remplacement conserve une sauvegarde vérifiée du paquet sous <code>&lt;ATLAS_PLUGIN_DATA_ROOT&gt;/.recovery</code>, dans le volume persistant existant et exclue des fichiers publics des plugins. Dans le gestionnaire, Importer un paquet remplace un plugin existant seulement après un aperçu et Sauvegarder et appliquer. Restaurer propose les versions sauvegardées. Le sens du changement de version et les capacités sont visibles ; une compatibilité inconnue exige une confirmation, une incompatibilité connue bloque l’application. Les aperçus périmés sont refusés. Fichiers et métadonnées partagées sont repris ensemble, en conservant activation et dépôts. Une restauration sauvegarde aussi la version actuellement installée.</p><p>Cette fonction restaure le code du plugin. Identifiants, projets, collections du navigateur et formats de données des plugins ne sont ni réinitialisés ni migrés. Des sauvegardes complètes et des données correspondantes restent nécessaires. Limites par plugin : 300 fichiers/20 MB par sauvegarde, 256 MiB et 200 sauvegardes au total. Aucune suppression automatique ; un stockage plein ou illisible bloque le remplacement. Le Card Editor intégré reste mis à jour avec ATLAS. Le périmètre natif vérifié est décrit ci-dessous.</p><h2 id="perimetre-verifie" tabindex="-1">Périmètre vérifié <a class="header-anchor" href="#perimetre-verifie" aria-label="Permalink to &quot;Périmètre vérifié&quot;">​</a></h2><p>La véritable mise à jour HACS de l’intégration 0.1.301 → 0.1.306 et les redémarrages HA réussissent sur Pi 5 et Proxmox en conservant paramètres, projets et plugins. Retour arrière et nouvelle mise à jour réussissent aussi isolément. Le format reste 1.1 ; un format inconnu 1.2 est refusé sans réécriture. L’intégration est vérifiée avec HA 2026.10.1 et aussi 2026.9.4 isolément. Autres versions et conversions réelles entre formats différents restent ouvertes. Les nouvelles migrations nécessitent des tests des formats anciens, actuels et inconnus, des échecs, conflits et restaurations.</p><p>La restauration des paquets via l’interface est vérifiée isolément puis sur Pi 5 et Proxmox pour Icon Library, File Studio et Terminal. Fichiers originaux, projets, autres plugins et paramètres contrôlés sont conservés. Ce n’est pas un retour arrière générique des données de tout plugin. La restauration HAOS complète séparée avec corbeille/historique et autre IP est décrite dans le <a href="./../file-studio">guide File Studio</a>.</p><p>La <a href="https://github.com/rockbaer2007/atlas/blob/main/docs/project/specifications/VERSION_COMPATIBILITY_POLICY.md" target="_blank" rel="noreferrer">politique technique du dépôt source</a> précise les règles et leurs limites.</p>',23)])])}const v=s(r,[["render",a]]);export{m as __pageData,v as default};
